-- The IDEA Club: the first batch of outside programs for Club → Opportunities
-- (49 programs), each listed under an unclaimed organization (migration
-- 20270325000000_opportunity_catalog.sql). Everything lands as a draft: nothing
-- appears publicly until an editor approves it in Staff → Club → Opportunities.
--
-- Safe to run again. A program is matched by slug and is only updated while it
-- is still the import's own untouched draft: no author, never sent or reviewed,
-- and `updated_at = created_at`. Every write here keeps those two timestamps
-- equal (both are the transaction's now()), and any later change by an editor
-- or an organization moves `updated_at` on, so the import then leaves it alone.
-- A draft an editor deleted comes back on a re-run; reject it instead.
--
-- Hosts follow private.create_unclaimed_organization, written out here because
-- that function needs a signed-in editor and this file runs without one: the
-- oldest organization with this name and no members, or a new one. A host is
-- only looked up for a new program, so renaming or moving a host in Staff sticks.
do $do$
declare
  item jsonb;
  found_row public.opportunities;
  host_id uuid;
  host_label text;
  added integer := 0;
  updated integer := 0;
  kept integer := 0;
  hosts_added integer := 0;
  row_changed integer;
begin
  for item in
    select value from jsonb_array_elements($json$[
