{"slug": "arab-german-young-academy-agya", "kind": "scholarship", "host": "Arab-German Young Academy (AGYA)", "title_ar": "الأكاديمية العربية الألمانية للعلماء الشباب (AGYA)", "title_en": "Arab-German Young Academy (AGYA)", "summary_ar": "مكان لخمس سنوات في الأكاديمية العربية الألمانية للباحثين في بداية مسيرتهم بعد 3 إلى 10 سنوات من الدكتوراه، العاملين في جامعة أو معهد في ألمانيا أو بلد عربي، والعراق مذكور بينها. توفر تمويلًا للمشاريع ومنحًا للسفر دون ذكر مبلغ.", "summary_en": "A five-year place in the Arab-German Young Academy for early-career researchers 3-10 years after their PhD, at a university or institute in Germany or an Arab country; Iraq is named. Offers project funding and travel grants; no amount stated.", "location": "Germany and Arab countries", "remote": false, "apply_url": "https://agya.info/about-us/call-for-members", "applicant_fee": 0, "fee_note": null, "opens_at": null, "deadline": null, "levels": ["postdoc"], "min_age": null, "max_age": null, "destination_countries": ["DE"], "funding_type": "partly_funded", "iraqi_eligibility": "named_official", "source_url": "https://agya.info/about-us/call-for-members", "last_checked_on": "2026-11-04"},
{"slug": "banach-scholarship-programme", "kind": "scholarship", "host": "NAWA (Poland)", "title_ar": "برنامج منح Banach", "title_en": "Banach Scholarship Programme", "summary_ar": "منحة من الحكومة البولندية عبر NAWA لدراسة الماجستير مع سنة تحضيرية اختيارية، لخريجي البلدان المشمولة ومنها العراق ممن حصلوا على البكالوريوس في 2024 أو بعدها. تدفع 2,500 زلوتي شهريًا مع إعفاء من الرسوم في الجامعات الحكومية ومبلغًا مقطوعًا للسفر.", "summary_en": "A Polish government scholarship from NAWA for second-cycle master's study, with an optional preparatory year, for graduates from covered countries including Iraq with a bachelor's dated 2024 or later. Pays PLN 2,500 a month, a tuition exemption at public universities and a travel lump sum.", "location": "Poland", "remote": false, "apply_url": "https://nawa.gov.pl/en/students/foreign-students/the-banach-scholarship-programme/information-for-applicants", "applicant_fee": 0, "fee_note": null, "opens_at": null, "deadline": null, "levels": ["masters"], "min_age": null, "max_age": null, "destination_countries": ["PL"], "funding_type": "fully_funded", "iraqi_eligibility": "named_official", "source_url": "https://www.nawa.gov.pl/images/Banach/2026/Banach-2026---Call-for-applications-EN.pdf", "last_checked_on": "2026-11-04"},
{"slug": "chevening-scholarships", "kind": "scholarship", "host": "UK Foreign, Commonwealth and Development Office (FCDO)", "title_ar": "منحة Chevening", "title_en": "Chevening Scholarships", "summary_ar": "منحة ماجستير ممولة بالكامل لمدة سنة في المملكة المتحدة من وزارة الخارجية والكومنولث والتنمية البريطانية، ولها صفحة خاصة بالعراق ودون حد أعلى للعمر. تشمل الرسوم والسفر بالدرجة الاقتصادية والمخصصات والتأشيرة وفحص السل وراتبًا شهريًا. أُغلقت دورة 2027-28.", "summary_en": "A fully funded one-year master's scholarship in the UK from the Foreign, Commonwealth and Development Office, with an Iraq page and no upper age limit. Covers tuition, economy travel, allowances, visa, a TB test and a monthly stipend. The 2027-28 round has closed.", "location": "United Kingdom", "remote": false, "apply_url": "https://www.chevening.org/scholarship/iraq/", "applicant_fee": 0, "fee_note": null, "opens_at": null, "deadline": null, "levels": ["masters"], "min_age": null, "max_age": null, "destination_countries": ["GB"], "funding_type": "fully_funded", "iraqi_eligibility": "named_official", "source_url": "https://www.chevening.org/scholarship/iraq/", "last_checked_on": "2026-11-04"},
{"slug": "daad-research-grants-in-germany", "kind": "scholarship", "host": "DAAD", "title_ar": "منح DAAD البحثية في ألمانيا", "title_en": "DAAD Research Grants in Germany", "summary_ar": "منح بحثية من DAAD في ألمانيا لطلبة الدكتوراه (من 2 إلى 12 شهرًا) وما بعد الدكتوراه (من 2 إلى 6 أشهر)، لمن يدرسون الدكتوراه خارج ألمانيا أو أنهوها خلال 4 سنوات. تدفع 1,400 يورو شهريًا و460 يورو للبحث كل 6 أشهر. أُغلق التقديم لتمويل مايو 2027.", "summary_en": "DAAD research stays in Germany for doctoral candidates (2-12 months) and postdocs (2-6 months), with a doctorate under way abroad or completed within four years. Pays EUR 1,400 a month and EUR 460 research allowance over six months. Funding from May 2027 has closed; the next date is not set.", "location": "Germany", "remote": false, "apply_url": "https://www.daad-iraq.org/en/find-funding/scholarship-database/?type=a&q=Research+Grants&status=0&subject=0&onlydaad=0&detail_to_show=57742121&target=88&origin=88&pg=1&tab=&intention=", "applicant_fee": 0, "fee_note": null, "opens_at": null, "deadline": null, "levels": ["phd", "postdoc"], "min_age": null, "max_age": null, "destination_countries": ["DE"], "funding_type": "stipend_only", "iraqi_eligibility": "named_official", "source_url": "https://www2.daad.de/deutschland/stipendium/datenbank/en/21148-scholarship-database/?origin=88&status=&subjectGrps=&daad=&intention=&q=&page=1&detail=57742121", "last_checked_on": "2026-11-04"},
