{"slug": "mansoura-university-summer-training-programs", "kind": "program", "host": "Mansoura University", "title_ar": "البرامج التدريبية الصيفية في جامعة المنصورة", "title_en": "Mansoura University Summer Training Programs", "summary_ar": "تدريب صيفي لمدة أسبوع في جامعة المنصورة في مصر للطلبة في كل المراحل، أعلنته جامعة المستقبل لشهري يوليو وأغسطس 2026. كانت الرسوم 300 دولار لكل طالب وتشمل السكن والوجبات والتدريب، وهو غير ممول. لم تُعلن جولة لاحقة.", "summary_en": "One-week summer training at Mansoura University in Egypt, for students at all stages, advertised by Al-Mustaqbal University for July-August 2026. It charged $300 per student, covering housing, meals and training; it is not funded. No later round is posted.", "location": "Mansoura University, Egypt", "remote": false, "apply_url": null, "applicant_fee": 0, "fee_note": "$300 per student, covering housing, meals and training.", "opens_at": null, "deadline": null, "levels": [], "min_age": null, "max_age": null, "destination_countries": ["EG"], "funding_type": "fee_charging", "iraqi_eligibility": "named_relay", "source_url": "https://uomus.edu.iq/CollegeEn/Details/114979", "last_checked_on": "2026-11-04"},
{"slug": "romanian-government-scholarships", "kind": "scholarship", "host": "Government of Romania", "title_ar": "منح الحكومة الرومانية", "title_en": "Romanian Government Scholarships", "summary_ar": "منح حكومية رومانية لمواطني الدول غير الأعضاء في الاتحاد الأوروبي للبكالوريوس والماجستير والدكتوراه، عدا الطب وطب الأسنان والصيدلة، بمعدل 7 فأكثر. تُصرف بالعملة الرومانية، مع سنة تحضيرية في اللغة الرومانية عند الحاجة. لا تشمل السكن الجامعي والنفقات الشخصية والسفر الدولي.", "summary_en": "Romanian state scholarships for non-EU citizens for bachelor's, master's and PhD study, excluding medicine, dentistry and pharmacy, with an average of 7 or more. Paid in lei, with a preparatory Romanian year if needed. Dorm housing, personal costs and international travel are not covered.", "location": "Romania", "remote": false, "apply_url": "https://scholarships.studyinromania.gov.ro", "applicant_fee": 0, "fee_note": null, "opens_at": null, "deadline": null, "levels": ["undergraduate", "masters", "phd"], "min_age": null, "max_age": null, "destination_countries": ["RO"], "funding_type": "partly_funded", "iraqi_eligibility": "inferred", "source_url": "https://www.studyinromania.gov.ro/scholarships", "last_checked_on": "2026-11-04"},
{"slug": "russian-government-scholarship-quota", "kind": "scholarship", "host": "Rossotrudnichestvo", "title_ar": "الحصة الحكومية الروسية للمنح", "title_en": "Russian Government Scholarship Quota", "summary_ar": "مقاعد من الحكومة الروسية للبكالوريوس والماجستير والدكتوراه عبر Rossotrudnichestvo، للموظفين وغير الموظفين في العراق، من خلال وزارة التعليم العالي. تشمل دراسة بلا رسوم وراتبًا شهريًا وسكنًا بكلفة قليلة وسنة لغة. لم تُنشر مواعيد العراق لعام 2027/28.", "summary_en": "Russian government places for bachelor's, master's and PhD study from Rossotrudnichestvo, for Iraqi employees and non-employees, through Iraq's Ministry of Higher Education. Free tuition, a monthly stipend, a low-fee dorm and a language year. Iraq's 2027/28 dates are not posted.", "location": "Russia", "remote": false, "apply_url": "https://education-in-russia.com/", "applicant_fee": 0, "fee_note": null, "opens_at": null, "deadline": null, "levels": ["undergraduate", "masters", "phd"], "min_age": null, "max_age": null, "destination_countries": ["RU"], "funding_type": "partly_funded", "iraqi_eligibility": "named_relay", "source_url": "https://en.misis.ru/applicants/scholarships/quota/", "last_checked_on": "2026-11-04"},
{"slug": "stipendium-hungaricum", "kind": "scholarship", "host": "Tempus Public Foundation", "title_ar": "Stipendium Hungaricum", "title_en": "Stipendium Hungaricum", "summary_ar": "منحة من الحكومة المجرية للبكالوريوس والماجستير والدكتوراه، بترشيح من وزارة التعليم العالي العراقية. تشمل الرسوم وراتبًا شهريًا ومكانًا في السكن الجامعي أو دعمًا للسكن وتأمينًا صحيًا. لم يُعثر بعد على إعلان 2027/28.", "summary_en": "A Hungarian government scholarship for bachelor's, master's and PhD study, by nomination from Iraq's Ministry of Higher Education. Covers tuition, a monthly stipend, a dorm place or housing support and medical insurance. No 2027/28 call has been found yet.", "location": "Hungary", "remote": false, "apply_url": "https://stipendiumhungaricum.hu/apply/", "applicant_fee": 0, "fee_note": null, "opens_at": null, "deadline": null, "levels": ["undergraduate", "masters", "phd"], "min_age": null, "max_age": null, "destination_countries": ["HU"], "funding_type": "partly_funded", "iraqi_eligibility": "named_relay", "source_url": "https://stipendiumhungaricum.hu/apply/", "last_checked_on": "2026-11-04"},
{"slug": "zayed-sustainability-prize-global-high-schools", "kind": "competition", "host": "Zayed Sustainability Prize", "title_ar": "جائزة زايد للاستدامة، فئة المدارس الثانوية العالمية", "title_en": "Zayed Sustainability Prize, Global High Schools", "summary_ar": "جائزة مدرسية ضمن جائزة زايد للاستدامة، وقد فازت مدرسة المتميزين في نينوى بالمركز الأول بين مدارس الشرق الأوسط وشمال أفريقيا الثانوية عام 2023. تحصل 6 مدارس فائزة على 150,000 دولار لكل منها، والمدارس المتأهلة على 25,000 دولار. أُغلق التقديم في يونيو 2026، ويقام الحفل في يناير 2027.", "summary_en": "A school award from the Zayed Sustainability Prize; Iraq's Nineveh Gifted School won first place for MENA secondary schools in 2023. Six winning schools get US$150,000 each and finalists US$25,000. Submissions closed in June 2026, with the ceremony in January 2027.", "location": "United Arab Emirates", "remote": false, "apply_url": "https://www.zayedsustainabilityprize.com/", "applicant_fee": 0, "fee_note": null, "opens_at": null, "deadline": null, "levels": ["high_school"], "min_age": null, "max_age": null, "destination_countries": ["AE"], "funding_type": "unknown", "iraqi_eligibility": "named_relay", "source_url": "https://www.zayedsustainabilityprize.com/", "last_checked_on": "2026-11-04"}
]$json$::jsonb)
  loop
    select * into found_row
    from public.opportunities o
    where o.slug = item ->> 'slug'
    for update;

    if found then
      if found_row.status <> 'draft'
        or found_row.created_by is not null
        or found_row.updated_at <> found_row.created_at
        or found_row.submitted_at is not null
        or found_row.reviewed_at is not null
        or found_row.review_note is not null
      then
        kept := kept + 1;
        continue;
      end if;

      update public.opportunities o set
        kind = (item ->> 'kind')::public.opportunity_kind,
        title_ar = item ->> 'title_ar',
        title_en = item ->> 'title_en',
        summary_ar = item ->> 'summary_ar',
        summary_en = item ->> 'summary_en',
        location = item ->> 'location',
        remote = (item ->> 'remote')::boolean,
        apply_url = item ->> 'apply_url',
        applicant_fee = (item ->> 'applicant_fee')::bigint,
        fee_note = item ->> 'fee_note',
        opens_at = (item ->> 'opens_at')::timestamptz,
        deadline = (item ->> 'deadline')::timestamptz,
        levels = array(select jsonb_array_elements_text(item -> 'levels'))::public.opportunity_level[],
        min_age = (item ->> 'min_age')::smallint,
        max_age = (item ->> 'max_age')::smallint,
        destination_countries = array(select jsonb_array_elements_text(item -> 'destination_countries')),
        funding_type = (item ->> 'funding_type')::public.opportunity_funding,
        iraqi_eligibility = (item ->> 'iraqi_eligibility')::public.opportunity_eligibility,
        source_url = item ->> 'source_url',
        last_checked_on = (item ->> 'last_checked_on')::date,
        created_at = now()
      where o.id = found_row.id
        and (
          o.kind, o.title_ar, o.title_en, o.summary_ar, o.summary_en, o.location, o.remote,
          o.apply_url, o.applicant_fee, o.fee_note, o.opens_at, o.deadline, o.levels,
          o.min_age, o.max_age, o.destination_countries, o.funding_type,
          o.iraqi_eligibility, o.source_url, o.last_checked_on
        ) is distinct from (
          (item ->> 'kind')::public.opportunity_kind,
          item ->> 'title_ar', item ->> 'title_en', item ->> 'summary_ar', item ->> 'summary_en',
          item ->> 'location', (item ->> 'remote')::boolean, item ->> 'apply_url',
          (item ->> 'applicant_fee')::bigint, item ->> 'fee_note',
          (item ->> 'opens_at')::timestamptz, (item ->> 'deadline')::timestamptz,
          array(select jsonb_array_elements_text(item -> 'levels'))::public.opportunity_level[],
          (item ->> 'min_age')::smallint, (item ->> 'max_age')::smallint,
          array(select jsonb_array_elements_text(item -> 'destination_countries')),
          (item ->> 'funding_type')::public.opportunity_funding,
          (item ->> 'iraqi_eligibility')::public.opportunity_eligibility,
          item ->> 'source_url', (item ->> 'last_checked_on')::date
        );
      get diagnostics row_changed = row_count;
      updated := updated + row_changed;
      continue;
    end if;

    host_label := trim(item ->> 'host');
    host_id := null;
    select g.id into host_id
    from public.organizations g
    where lower(g.name) = lower(host_label)
      and not exists (select 1 from public.organization_members m where m.organization_id = g.id)
    order by g.created_at
    limit 1;

    if host_id is null then
      insert into public.organizations (name, slug, features)
      values (
        host_label,
        left(
          coalesce(
            nullif(trim(both '-' from regexp_replace(lower(host_label), '[^a-z0-9]+', '-', 'g')), ''),
            'organization'
          ),
          57
        ) || '-' || substr(md5(gen_random_uuid()::text), 1, 6),
        '{opportunities}'
      )
      returning id into host_id;
      hosts_added := hosts_added + 1;
    end if;

    insert into public.opportunities (
      slug, organization_id, status, kind, title_ar, title_en, summary_ar, summary_en,
      location, remote, apply_url, applicant_fee, fee_note, opens_at, deadline, levels,
      min_age, max_age, destination_countries, funding_type, iraqi_eligibility,
      source_url, last_checked_on
    ) values (
      item ->> 'slug', host_id, 'draft',
      (item ->> 'kind')::public.opportunity_kind,
      item ->> 'title_ar', item ->> 'title_en', item ->> 'summary_ar', item ->> 'summary_en',
      item ->> 'location', (item ->> 'remote')::boolean, item ->> 'apply_url',
      (item ->> 'applicant_fee')::bigint, item ->> 'fee_note',
      (item ->> 'opens_at')::timestamptz, (item ->> 'deadline')::timestamptz,
      array(select jsonb_array_elements_text(item -> 'levels'))::public.opportunity_level[],
      (item ->> 'min_age')::smallint, (item ->> 'max_age')::smallint,
      array(select jsonb_array_elements_text(item -> 'destination_countries')),
      (item ->> 'funding_type')::public.opportunity_funding,
      (item ->> 'iraqi_eligibility')::public.opportunity_eligibility,
      item ->> 'source_url', (item ->> 'last_checked_on')::date
    );
    added := added + 1;
  end loop;

  raise notice 'Opportunities: % added, % updated, % left alone; % new hosts', added, updated, kept, hosts_added;
end;
$do$;
